corporate_design.toad_component_blueprint:
canvas {
  size: 900px 580px;
  fill: #F0F9FF;
  font-family: "Plus Jakarta Sans, sans-serif";
}

>teal = #0284C7;
>white = #FFFFFF;

rect #cardSmile {
  at: center of canvas;
  size: 800px 480px;
  fill: >white;
  radius: 24px;
}

text #dentTitle {
  at: top left of #cardSmile offset 40px 40px;
  content: "DENTAPUR // ÄSTHETISCHE ZAHNMEDIZIN";
  font-size: 13px;
  font-weight: 700;
  color: >teal;
}

text #smileHeadline {
  at: below #dentTitle offset 16px;
  content: "Dein schönstes Lächeln – schmerzfrei & unsichtbar";
  font-size: 30px;
  font-weight: 600;
  color: #0F172A;
}
